SELECT * FROM customer_shopping_da4.customer;

-- 1. What is total revenue generated by male vs female customers?
select gender, SUM(purchase_amount) as revenue from customer group by gender;

-- 2. Which customer used a discount but still spent more than the average purchase amount?
select customer_id, purchase_amount
from customer
where discount_applied = 'Yes' and purchase_amount >= (select AVG(purchase_amount) from customer);


-- 3. Which are the top 5 products with the highest average review rating?
select item_purchased, round(avg(review_rating),2) as "Average Product Rating"
from customer
group by item_purchased
order by avg(review_rating) desc
limit 5;


-- 4. Compare the average purchase amounts between Standard and Express Shipping
select shipping_type,
ROUND(AVG(purchase_amount),2)
from customer
where shipping_type in ('Standard', 'Express')
group by shipping_type;


-- 5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.
select subscription_status,
COUNT(customer_id) as total_customer,
ROUND(AVG(purchase_amount),2) as avg_spend,
ROUND(AVG(purchase_amount),2) as total_revenue
from customer group by subscription_status
order by total_revenue, avg_spend desc;

-- 6. Which 5 products have the highest percentage of purchases with discounts applied?
select item_purchased,
ROUND(100.0 * SUM(case when discount_applied = 'Yes' then 1 else 0 end)/COUNT(*),2) as discount_rate
from customer
group by item_purchased
order by discount_rate desc
limit 5;

-- 7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segment. 
with customer_type as (
SELECT customer_id, previous_purchases,
case
when previous_purchases = 1 then 'New'
when previous_purchases between 2 and 10 then 'Returning'
else 'Loyal'
end as customer_segment
from customer)

select customer_segment, count(*) as "Number of Customer"
from customer_type
group by customer_segment;

-- 8. What are the top 3 most purchased products within each category? 
with item_counts AS(
select category,
item_purchased,
count(customer_id) as total_orders,
ROW_NUMBER() over (PARTITION BY category ORDER BY count(customer_id) desc) as item_rank
from customer
group by category, item_purchased
)
select item_rank, category, item_purchased, total_orders
from item_counts
where item_rank <= 3;


-- 9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select subscription_status,
count(customer_id) as repeat_buyers
from customer
where previous_purchases > 5
group by subscription_status;


-- 10. What is the revenue contribution of each age group?
select 
age_group,
sum(purchase_amount) as total_revenue
from customer 
group by age_group
order by total_revenue desc;